import{_ as t,o as e,c as i,a6 as s}from"./chunks/framework.BrkgobfX.js";const g=JSON.parse('{"title":"迁移注意事项","description":"哪些 1.1 知识作废、哪些照旧，以及升级 h2/h3 时真正会踩的坑。","frontmatter":{"title":"迁移注意事项","description":"哪些 1.1 知识作废、哪些照旧，以及升级 h2/h3 时真正会踩的坑。","source":"https://daiw.org/manual/http2-3/migration-notes"},"headers":[],"relativePath":"manual/computer-programming/http2-3/migration-notes.md","filePath":"manual/computer-programming/http2-3/migration-notes.md"}'),n={name:"manual/computer-programming/http2-3/migration-notes.md"};function r(l,a,o,h,p,d){return e(),i("div",null,[...a[0]||(a[0]=[s('<h1 id="迁移注意事项" tabindex="-1">迁移注意事项 <a class="header-anchor" href="#迁移注意事项" aria-label="Permalink to &quot;迁移注意事项&quot;">​</a></h1><p>哪些 1.1 知识作废、哪些照旧，以及升级 h2/h3 时真正会踩的坑。</p><h2 id="哪些-1-1-知识作废" tabindex="-1">哪些 1.1 知识作废 <a class="header-anchor" href="#哪些-1-1-知识作废" aria-label="Permalink to &quot;哪些 1.1 知识作废&quot;">​</a></h2><p>从 <a href="/Front2Full/manual/computer-programming/http11/">HTTP/1.1 专栏</a>带过来的内容里，**只有第 1 部分（报文与成帧）**在 h2/h3 上失效：</p><table tabindex="0"><thead><tr><th>作废的</th><th>替代</th></tr></thead><tbody><tr><td><a href="/Front2Full/manual/computer-programming/http11/message-format">报文四段式结构</a>、CRLF、obs-fold</td><td>二进制帧</td></tr><tr><td><a href="/Front2Full/manual/computer-programming/http11/request-line">request-line / status-line</a></td><td>伪头字段</td></tr><tr><td><a href="/Front2Full/manual/computer-programming/http11/message-body-length">七步成帧判定链</a></td><td>帧长 + <code>END_STREAM</code>/FIN</td></tr><tr><td><code>Transfer-Encoding</code>、<code>chunked</code></td><td>帧层负责</td></tr><tr><td><a href="/Front2Full/manual/computer-programming/http11/connection-management"><code>Connection</code>、<code>Keep-Alive</code>、<code>Upgrade</code></a></td><td>ALPN + <code>SETTINGS</code> + <code>GOAWAY</code></td></tr><tr><td>流水线、逐跳字段概念</td><td>流多路复用</td></tr></tbody></table><h2 id="哪些照旧" tabindex="-1">哪些照旧 <a class="header-anchor" href="#哪些照旧" aria-label="Permalink to &quot;哪些照旧&quot;">​</a></h2><p>第 2、3 部分<strong>逐字有效</strong>，三版通用：</p><ul><li>全部<a href="/Front2Full/manual/computer-programming/http11/methods">方法</a>及其安全/幂等/可缓存性</li><li>全部<a href="/Front2Full/manual/computer-programming/http11/status-codes">状态码</a></li><li>全部字段语义：<a href="/Front2Full/manual/computer-programming/http11/representation-fields">表示</a>、<a href="/Front2Full/manual/computer-programming/http11/content-negotiation">协商</a>、<a href="/Front2Full/manual/computer-programming/http11/conditional-requests">条件</a>、<a href="/Front2Full/manual/computer-programming/http11/range-requests">范围</a>、<a href="/Front2Full/manual/computer-programming/http11/caching">缓存</a>、<a href="/Front2Full/manual/computer-programming/http11/authentication">认证</a>、<a href="/Front2Full/manual/computer-programming/http11/cookies">Cookie</a></li></ul><p><strong>升级协议不改变任何业务语义。</strong><code>ETag</code> 还是那个 <code>ETag</code>，<code>Cache-Control</code> 还是那套规则。</p><h2 id="应用层几乎不用改" tabindex="-1">应用层几乎不用改 <a class="header-anchor" href="#应用层几乎不用改" aria-label="Permalink to &quot;应用层几乎不用改&quot;">​</a></h2><p>对绝大多数应用，升级 h2/h3 是<strong>纯运维动作</strong>——终结点（nginx / CDN / 网关）改配置即可，应用代码不动。因为：</p><ul><li>网关会自动完成 h2/h3 ↔ 1.1 的转换。</li><li>框架（Express、Spring、Go net/http）对上层暴露的是同一套请求/响应对象。</li></ul><p>需要改代码的少数情况见下。</p><h2 id="真正会踩的坑" tabindex="-1">真正会踩的坑 <a class="header-anchor" href="#真正会踩的坑" aria-label="Permalink to &quot;真正会踩的坑&quot;">​</a></h2><h3 id="_1-字段名大小写" tabindex="-1">1. 字段名大小写 <a class="header-anchor" href="#_1-字段名大小写" aria-label="Permalink to &quot;1. 字段名大小写&quot;">​</a></h3><p>h2/h3 <strong>强制小写</strong>。若代码里有：</p><div class="language-js vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (req.headers[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Content-Type&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">===</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// h2 下永远取不到</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>必须改为小写查找。多数框架已归一化，但<strong>自己拼原始头</strong>或用底层库时要注意。</p><h3 id="_2-依赖-1-1-特有字段的逻辑" tabindex="-1">2. 依赖 1.1 特有字段的逻辑 <a class="header-anchor" href="#_2-依赖-1-1-特有字段的逻辑" aria-label="Permalink to &quot;2. 依赖 1.1 特有字段的逻辑&quot;">​</a></h3><div class="language-js vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (req.headers.connection </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">===</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;keep-alive&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// h2/h3 下该字段不存在</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (req.headers[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;transfer-encoding&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">])         </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 同上</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>这些字段在 h2/h3 中<strong>被禁止出现</strong>，相关判断会静默失效。</p><h3 id="_3-域名分片要撤掉" tabindex="-1">3. 域名分片要撤掉 <a class="header-anchor" href="#_3-域名分片要撤掉" aria-label="Permalink to &quot;3. 域名分片要撤掉&quot;">​</a></h3><p>1.1 时代把静态资源拆到 <code>img1.example.com</code>、<code>img2.example.com</code> 以突破 6 连接限制。h2/h3 下这是<strong>负优化</strong>：每个域要单独握手、单独维护连接与压缩上下文。<strong>合并回单域</strong>。</p><p>同理，<strong>资源合并（雪碧图、打包成一个巨型 JS）的收益也大幅下降</strong>——多路复用后小文件不再昂贵，且细粒度更利于缓存命中。但也不必走极端拆成上千个小文件，请求本身仍有开销。</p><h3 id="_4-initial-window-size-默认值太小" tabindex="-1">4. <code>INITIAL_WINDOW_SIZE</code> 默认值太小 <a class="header-anchor" href="#_4-initial-window-size-默认值太小" aria-label="Permalink to &quot;4. `INITIAL_WINDOW_SIZE` 默认值太小&quot;">​</a></h3><p>h2 默认 65535 字节。跨洋 100ms RTT 下单流吞吐上限约 <strong>640 KB/s</strong>——大文件下载会明显变慢，且这个现象常被误判为「h2 比 1.1 慢」。</p><p>nginx 示例：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http2_body_preread_size    64k;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>更关键的是上游代理与应用服务器的窗口设置，需逐层检查。</p><h3 id="_5-max-concurrent-streams-必须设有限值" tabindex="-1">5. <code>MAX_CONCURRENT_STREAMS</code> 必须设有限值 <a class="header-anchor" href="#_5-max-concurrent-streams-必须设有限值" aria-label="Permalink to &quot;5. `MAX_CONCURRENT_STREAMS` 必须设有限值&quot;">​</a></h3><p>规范默认<strong>无限</strong>。不设置等于对流洪泛不设防（含 <strong>Rapid Reset</strong> CVE-2023-44487）。生产建议 100–128，并<strong>额外限制单位时间内的 <code>RST_STREAM</code> 速率</strong>。</p><h3 id="_6-0-rtt-的重放风险" tabindex="-1">6. 0-RTT 的重放风险 <a class="header-anchor" href="#_6-0-rtt-的重放风险" aria-label="Permalink to &quot;6. 0-RTT 的重放风险&quot;">​</a></h3><p>启用 h3 的 0-RTT 时，<strong>非幂等请求可能被重放</strong>。要么：</p><ul><li>服务端对 0-RTT 中的非幂等请求返回 <a href="/Front2Full/manual/computer-programming/http11/status-4xx"><code>425 Too Early</code></a>；</li><li>要么实现请求去重（幂等键）。</li></ul><p>不要在没有防护的情况下对写接口开 0-RTT。</p><h3 id="_7-udp-必须可回落" tabindex="-1">7. UDP 必须可回落 <a class="header-anchor" href="#_7-udp-必须可回落" aria-label="Permalink to &quot;7. UDP 必须可回落&quot;">​</a></h3><p>h3 依赖 UDP/443 可达。<strong>必须</strong>同时保留 h2/1.1 端点，并确认防火墙放行 UDP 443。只开 h3 会让部分用户完全无法访问。</p><h3 id="_8-可观测性要重建" tabindex="-1">8. 可观测性要重建 <a class="header-anchor" href="#_8-可观测性要重建" aria-label="Permalink to &quot;8. 可观测性要重建&quot;">​</a></h3><p>QUIC 加密了传输层元数据，传统抓包分析（RTT、重传、窗口）<strong>失效</strong>。需要：</p><ul><li>启用 <strong>qlog</strong>（端点导出的结构化传输日志）。</li><li>在应用层补齐指标：按协议版本分别统计延迟、错误率、连接复用率。</li></ul><h2 id="部署检查清单" tabindex="-1">部署检查清单 <a class="header-anchor" href="#部署检查清单" aria-label="Permalink to &quot;部署检查清单&quot;">​</a></h2><ul><li>[ ] TLS 1.2+ 且启用 ALPN；h3 需 TLS 1.3（Nginx 1.25+ 原生支持 <code>http2 on;</code> 与 <code>listen 443 quic; http3 on;</code>）。</li><li>[ ] 证书链完整（h2 对 TLS 配置更严，禁用重协商与压缩）。</li><li>[ ] 防火墙放行 <strong>UDP 443</strong>（h3）。</li><li>[ ] 下发 <code>Alt-Svc</code>，并考虑配置 DNS <strong>HTTPS 记录</strong>以省掉首访的一跳。</li><li>[ ] <code>MAX_CONCURRENT_STREAMS</code> 有限值 + <code>RST_STREAM</code> 速率限制。</li><li>[ ] 窗口大小按带宽延迟积调整。</li><li>[ ] <code>MAX_HEADER_LIST_SIZE</code> 显式设置（防 HPACK 炸弹）。</li><li>[ ] 撤销域名分片，收敛到单域。</li><li>[ ] 保留 h2 与 1.1 回落路径并实测。</li><li>[ ] 用 <code>curl --http2</code> / <code>--http3</code> 与浏览器 DevTools 的 Protocol 列逐一验证。</li></ul><p>验证命令：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -sI</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --http3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://example.com</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> head</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -1</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -sI</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --http2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://example.com</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> head</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -1</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="收尾" tabindex="-1">收尾 <a class="header-anchor" href="#收尾" aria-label="Permalink to &quot;收尾&quot;">​</a></h2><p>三版协议的关系可以用一句话概括：</p><blockquote><p><strong>HTTP 语义从未改变，改的一直是「怎么把它装进字节」和「这些字节跑在什么之上」。</strong></p></blockquote><ul><li>HTTP/2 重写了<strong>装法</strong>（文本 → 二进制帧 + 多路复用 + 压缩）。</li><li>HTTP/3 重写了<strong>载体</strong>（TCP → QUIC），顺带把流管理与流量控制下沉。</li></ul><p>理解了这一点，<a href="/Front2Full/manual/computer-programming/http11/">HTTP/1.1 专栏</a>里关于方法、状态码与字段的每一条规则，在 h2 与 h3 上都可以原样复用——那才是 HTTP 真正稳定的部分。</p>',50)])])}const u=t(n,[["render",r]]);export{g as __pageData,u as default};
